package vn.contractgovernance.api.control;
import java.util.*;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import vn.contractgovernance.api.obligation.ServiceEndProof;
import vn.contractgovernance.api.shared.*;
import static vn.contractgovernance.api.change.ChangeService.id;
/** Historical independent observation, not mutable service-state inference. */
@Service
public class ControlEndProof implements ServiceEndProof {
 private final EntityStore store;private final JsonSupport json;private final ControlService controls;private final ControlEvidence evidence;
 public ControlEndProof(EntityStore store,JsonSupport json,ControlService controls,ControlEvidence evidence){this.store=store;this.json=json;this.controls=controls;this.evidence=evidence;}
 @Override public boolean verifiedEnded(UUID contractId){var c=store.require("Contract",contractId);if(!Set.of("EXPIRED","TERMINATED").contains(c.body().path("state").asString())||!c.body().path("serviceState").asString().equals("STOPPED"))return false;var rows=store.jdbc().query("select request_id,revision_id,body::text,body_hash,assessed_by from cg_control_confirmation where contract_id=? and kind in ('STOP','TERMINATE') order by recorded_at desc,request_id desc",(rs,n)->List.of(rs.getObject(1,UUID.class).toString(),rs.getObject(2,UUID.class).toString(),rs.getString(3),rs.getString(4),rs.getObject(5,UUID.class).toString()),contractId);for(var row:rows){var request=store.require("ControlRequest",UUID.fromString(row.get(0)));var proof=json.parse(row.get(2));var source=controls.revision(UUID.fromString(row.get(1)),request.id());if(!request.body().path("state").asString().equals("CONFIRMED")||!json.hash(proof).equals(row.get(3))||!proof.path("sourceHash").asString().equals(source.hash())||!proof.path("assessedBy").asString().equals(row.get(4))||!proof.path("afterServiceState").asString().equals("STOPPED")||!proof.path("contractId").asString().equals(contractId.toString())||evidence.ids(proof.path("sourceContributors")).contains(UUID.fromString(row.get(4))))throw ApiException.of("STORAGE_INTEGRITY","Immutable ended-service proof mismatch.");for(String field:List.of("externalAcknowledgement","observedAt"))if(!request.body().path(field).equals(proof.path(field)))throw ApiException.of("STORAGE_INTEGRITY","Control observation differs from immutable proof.");if(!evidence.manifest(request,evidence.ids(proof.path("externalAcknowledgement").path("fileIds")),null,false).equals(proof.path("manifest"))||!evidence.manifest(request,evidence.ids(source.revision().path("evidenceFileIds")),null,false).equals(source.metadata().path("evidence")))throw ApiException.of("STORAGE_INTEGRITY","Ended-service bytes differ from assessment.");var artifactIds=new TreeSet<UUID>();for(var entry:source.metadata().path("artifact"))artifactIds.add(id(entry,"fileId"));if(!evidence.manifest(request,artifactIds,null,false).equals(source.metadata().path("artifact")))throw ApiException.of("STORAGE_INTEGRITY","Control source artifact bytes changed.");if(proof.path("neverStarted").asBoolean()&&!proof.path("beforeServiceState").asString().equals("NOT_STARTED"))throw ApiException.of("STORAGE_INTEGRITY","Never-started proof contradicts observed history.");return true;}return false;}
}
